const test = require("node:test");
const assert = require("node:assert");

const { canonicalizeQuery } = require("./urlutil");

test("params sorted by key", () => {
  const result = new URL(canonicalizeQuery("https://example.com/path?z=1&a=2&m=3"));
  const keys = [...result.searchParams.keys()];
  assert.deepStrictEqual(keys, ["a", "m", "z"]);
});

test("duplicate keys keep relative order", () => {
  const result = new URL(canonicalizeQuery("https://example.com/?b=2&a=second&b=1&a=first"));
  const pairs = [...result.searchParams.entries()];
  const aValues = pairs.filter(([k]) => k === "a").map(([, v]) => v);
  const bValues = pairs.filter(([k]) => k === "b").map(([, v]) => v);
  assert.deepStrictEqual(aValues, ["second", "first"]);
  assert.deepStrictEqual(bValues, ["2", "1"]);
});

test("scheme host path hash untouched", () => {
  const result = new URL(canonicalizeQuery("https://example.com/some/path?z=1&a=2#section"));
  assert.strictEqual(result.protocol, "https:");
  assert.strictEqual(result.host, "example.com");
  assert.strictEqual(result.pathname, "/some/path");
  assert.strictEqual(result.hash, "#section");
});

reference_solution.urlutil.js:
function canonicalizeQuery(url) {
  const parsed = new URL(url);
  const pairs = [...parsed.searchParams.entries()];
  const sorted = pairs
    .map((pair, index) => ({ pair, index }))
    .sort((a, b) => a.pair[0].localeCompare(b.pair[0]) || a.index - b.index)
    .map((entry) => entry.pair);
  const newParams = new URLSearchParams();
  for (const [k, v] of sorted) {
    newParams.append(k, v);
  }
  parsed.search = newParams.toString();
  return parsed.toString();
}

module.exports = { canonicalizeQuery };

